import axios from 'axios';
import { Note } from '../types';
import { StringMappingType } from 'typescript';

const API_URL = 'http://localhost:8080/api';

export const api = {
    getNotes: async (): Promise<Note[]> => {
        const response = await axios.get(`${API_URL}/notes`);
        return response.data;
    },

    getNote: async (id: number): Promise<Note> => {
        const response = await axios.get(`${API_URL}/notes/${id}`);
        return response.data;
    },

    createNote: async (note: Omit<Note, 'id' | 'created_at' | 'updated_at'>): Promise<Note> => {
        const response = await axios.post(`${API_URL}/notes`, note);
        return response.data;
    },

    updateNote: async (id: string, note: Partial<Note>): Promise<Note> => {
        const response = await axios.put(`${API_URL}/notes/${id}`, note);
        return response.data;
      },

    deleteNote: async (id: string): Promise<void> => {
        await axios.delete(`${API_URL}/notes/${id}`);
    },
    signup: async (username: string, password: string) => {
        return axios.post(`${API_URL}/signup`, { username, password });
      },
      login: async (username: string, password: string) => {
        return axios.post(`${API_URL}/login`, { username, password });
      },
};
